MinimumPairRestraint::MinimumPairRestraint(
    PairScore *f, PairContainerAdaptor c, unsigned int n,
    std::string name)
    : Restraint(c->get_model(), name), f_(f), c_(c), n_(n) {}

namespace {
typedef algebra::internal::MinimalSet<double, ParticleIndexPair, std::less<double> >
    PairMinimumMS;
template <class C, class F>
PairMinimumMS find_minimal_set_PairMinimum(C *c, F *f,
                                                     unsigned int n) {
  IMP_LOG_VERBOSE("Finding Minimum " << n << " of " << c->get_number()
                                     << std::endl);
  PairMinimumMS bestn(n);
  for(ParticleIndexPair it : c->get_contents()) {
    double score = f->evaluate_index(c->get_model(), it, nullptr);
    IMP_LOG_VERBOSE("Found " << score << " for " << it << std::endl);
    bestn.insert(score, it);
  }
  return bestn;
}
}

double MinimumPairRestraint::unprotected_evaluate(
    DerivativeAccumulator *da) const {
  IMP_OBJECT_LOG;
  PairMinimumMS bestn =
      find_minimal_set_PairMinimum(c_.get(), f_.get(), n_);

  double score = 0;
  for (unsigned int i = 0; i < bestn.size(); ++i) {
    if (da) {
      f_->evaluate_index(get_model(), bestn[i].second, da);
    }
    score += bestn[i].first;
  }
  IMP_LOG_VERBOSE("Total score is " << score << std::endl);
  return score;
}

double MinimumPairRestraint::unprotected_evaluate_if_good(
    DerivativeAccumulator *da, double max) const {
  IMP_OBJECT_LOG;
  PairMinimumMS bestn =
      find_minimal_set_PairMinimum(c_.get(), f_.get(), n_);

  double score = 0;
  for (unsigned int i = 0; i < bestn.size(); ++i) {
    if (da) {
      f_->evaluate_index(get_model(), bestn[i].second, da);
    }
    score += bestn[i].first;
    if (score > max) break;
  }
  IMP_LOG_VERBOSE("Total score is " << score << std::endl);
  return score;
}

Restraints MinimumPairRestraint::do_create_current_decomposition() const {
  IMP_OBJECT_LOG;
  PairMinimumMS bestn =
      find_minimal_set_PairMinimum(c_.get(), f_.get(), n_);
  Restraints ret;
  for (unsigned int i = 0; i < bestn.size(); ++i) {
    ret.push_back(IMP::internal::create_tuple_restraint(
        f_.get(), get_model(), bestn[i].second, get_name()));
    ret.back()->set_last_score(bestn[i].first);
  }
  return ret;
}

